/** Apply fitted first-party weights; fingerprints retain their original weights. */
export function reweightPacks(packs: RulePack[]): RulePack[] {
  return packs.map(pack => ({ ...pack, rules: pack.rules.flatMap(rule => {
    const weight = firstPartyWeights[rule.id] ?? rule.weight;
    return weight > 0 ? [{ ...rule, weight }] : [];
  }) }));
}

